// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 secondAmount) internal {
        secondAmount = bound(secondAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(secondAmount == 10);
        vm.assume(address(this).balance >= 20);
        uint256 prePot;
        try c.pot() returns (uint256 __r) { prePot = __r; } catch { return; }
        try c.play{value: 10}() {} catch { return; }
        vm.assume(c.pot() == prePot + 10);
        try c.play{value: secondAmount}() {} catch { return; }
        assertTrue(c.pot() == 20);
    }

    function testFuzz_test(uint256 secondAmount) public {
        _test(secondAmount);
    }

    receive() external payable {}
}
